package dev.szabotar.jorkonvo.push;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Scanner;
import org.json.JSONObject;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * Megolm.decrypt against vectors produced by vodozemac, the reference
 * implementation (src/test/resources/megolm_vectors.json, generated by
 * scripts/push/gen_megolm_vectors.py): one outbound session, messages at
 * indices across every ratchet-part boundary, exports at several indices.
 */
public class MegolmTest {

    private static JSONObject vectors;

    @BeforeClass
    public static void load() throws Exception {
        try (InputStream in = MegolmTest.class.getResourceAsStream("/megolm_vectors.json");
             Scanner s = new Scanner(in, StandardCharsets.UTF_8.name()).useDelimiter("\\A")) {
            vectors = new JSONObject(s.next());
        }
    }

    private static String export(int index) throws Exception {
        return vectors.getJSONObject("exports").getString(String.valueOf(index));
    }

    private static JSONObject message(int index) throws Exception {
        return vectors.getJSONObject("messages").getJSONObject(String.valueOf(index));
    }

    @Test
    public void decryptsEveryMessageFromTheIndexZeroExport() throws Exception {
        for (int i : new int[] {0, 1, 2, 255, 256, 257, 65535, 65536, 70000}) {
            JSONObject m = message(i);
            assertEquals("index " + i, m.getString("plaintext"), Megolm.decrypt(export(0), m.getString("ciphertext")));
        }
    }

    @Test
    public void decryptsFromLaterExports() throws Exception {
        assertEquals(message(2).getString("plaintext"), Megolm.decrypt(export(2), message(2).getString("ciphertext")));
        assertEquals(message(257).getString("plaintext"), Megolm.decrypt(export(256), message(257).getString("ciphertext")));
        assertEquals(message(70000).getString("plaintext"), Megolm.decrypt(export(65536), message(70000).getString("ciphertext")));
        assertEquals(message(65536).getString("plaintext"), Megolm.decrypt(export(256), message(65536).getString("ciphertext")));
    }

    @Test
    public void refusesMessagesBeforeTheKnownIndex() throws Exception {
        Megolm.DecryptionException e = assertThrows(
            Megolm.DecryptionException.class,
            () -> Megolm.decrypt(export(256), message(255).getString("ciphertext"))
        );
        assertTrue(e.getMessage(), e.getMessage().contains("before"));
    }

    @Test
    public void rejectsATamperedMessage() throws Exception {
        assertThrows(Megolm.DecryptionException.class, () -> Megolm.decrypt(export(0), vectors.getString("tampered_index1")));
    }

    @Test
    public void verifiesTheEd25519SignatureWhereAvailable() throws Exception {
        // MAC intact, only the trailing signature altered: must fail on a JVM
        // (Ed25519 since Java 15), proving the signature check isn't skipped.
        byte[] raw = java.util.Base64.getDecoder().decode(message(1).getString("ciphertext"));
        raw[raw.length - 1] ^= 1;
        String forged = java.util.Base64.getEncoder().withoutPadding().encodeToString(raw);
        Megolm.DecryptionException e = assertThrows(Megolm.DecryptionException.class, () -> Megolm.decrypt(export(0), forged));
        assertEquals("bad signature", e.getMessage());
    }

    @Test
    public void rejectsGarbage() {
        assertThrows(Megolm.DecryptionException.class, () -> Megolm.decrypt("AAAA", "AAAA"));
        assertThrows(Megolm.DecryptionException.class, () -> Megolm.decrypt("not base64!", "x"));
    }

    @Test
    public void base64AcceptsPaddedAndUnpadded() throws Exception {
        assertEquals("hello", new String(Megolm.unbase64("aGVsbG8"), StandardCharsets.UTF_8));
        assertEquals("hello", new String(Megolm.unbase64("aGVsbG8="), StandardCharsets.UTF_8));
    }
}
